-- Additive v6. Imported contacts never create accounts, sessions or subscriptions.
BEGIN;
SELECT pg_advisory_xact_lock(203008);
CREATE TABLE IF NOT EXISTS contact_imports(id uuid PRIMARY KEY,author_id text NOT NULL REFERENCES users(id),filename text NOT NULL,source text NOT NULL CHECK(source IN ('external','own_users','self_subscribed')),fingerprint text NOT NULL,counts jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days',UNIQUE(author_id,fingerprint,source));
CREATE TABLE IF NOT EXISTS external_contacts(identity text PRIMARY KEY,ciphertext text NOT NULL,import_id uuid NOT NULL REFERENCES contact_imports(id) ON DELETE CASCADE,source text NOT NULL,consent_status text NOT NULL DEFAULT 'unproven' CHECK(consent_status='unproven'),created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days');
CREATE TABLE IF NOT EXISTS email_preferences(user_id text PRIMARY KEY REFERENCES users(id),category text NOT NULL DEFAULT 'updates' CHECK(category='updates'),opt_in_at timestamptz,verified_at timestamptz,evidence_id uuid,opted_out_at timestamptz,consent_version text NOT NULL DEFAULT 'somas-updates-v1');
CREATE TABLE IF NOT EXISTS email_suppressions(identity text PRIMARY KEY,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS broadcast_campaigns(id uuid PRIMARY KEY,author_id text NOT NULL REFERENCES users(id),title text NOT NULL,subject text NOT NULL,body text NOT NULL,channel text NOT NULL CHECK(channel IN ('in_app','email')),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','queued','complete','cancelled','paused')),approved_by text REFERENCES users(id),snapshot_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS broadcast_recipients(campaign_id uuid NOT NULL REFERENCES broadcast_campaigns(id),user_id text NOT NULL REFERENCES users(id),identity text NOT NULL,unsubscribe_token text NOT NULL,status text NOT NULL DEFAULT 'snapshot' CHECK(status IN ('snapshot','queued','sending','accepted','notified','suppressed','uncertain','cancelled')),provider_id text,last_error text,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(campaign_id,user_id),UNIQUE(campaign_id,identity));
CREATE TABLE IF NOT EXISTS broadcast_events(id uuid PRIMARY KEY,actor_id text REFERENCES users(id),campaign_id uuid REFERENCES broadcast_campaigns(id),kind text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS in_app_announcements(id uuid PRIMARY KEY,campaign_id uuid NOT NULL REFERENCES broadcast_campaigns(id),user_id text NOT NULL REFERENCES users(id),subject text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),viewed_at timestamptz,UNIQUE(campaign_id,user_id));
CREATE INDEX IF NOT EXISTS broadcast_recipient_queue ON broadcast_recipients(status,updated_at);
CREATE INDEX IF NOT EXISTS announcement_user ON in_app_announcements(user_id,created_at);
REVOKE ALL ON contact_imports,external_contacts,email_preferences,email_suppressions,broadcast_campaigns,broadcast_recipients,broadcast_events,in_app_announcements FROM PUBLIC;
COMMIT;
